#include <iostream>
using namespace std;

bool isArmstrong(int n) {
    int digits = 0, t = n;
    while (t > 0) { digits++; t /= 10; }
    if (n >= 10) {
        long long s = 0; t = n;
        while (t > 0) {
            int d = t % 10; long long p = 1;
            for (int i = 0; i < digits; i++) p *= d;
            s += p; t /= 10;
        }
        return s == n;
    }
}

int main() {
    int n;
    cin >> n;
    bool ok = isArmstrong(n);
    cout << "Nhap n: " << (ok ? "True" : "False") << endl;
    return 0;
}
